CREATE TABLE IF NOT EXISTS ai_provider_fallbacks (id TEXT PRIMARY KEY,provider TEXT NOT NULL,base_url TEXT NOT NULL,model TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 0,config_json TEXT NOT NULL DEFAULT '{}',secret_ciphertext TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,updated_by TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ai_provider_health (id TEXT PRIMARY KEY,profile TEXT NOT NULL,provider TEXT NOT NULL,model TEXT NOT NULL,operation TEXT NOT NULL,status TEXT NOT NULL,latency_ms INTEGER NOT NULL DEFAULT 0,detail TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS ai_provider_health_created_idx ON ai_provider_health(created_at,status);
CREATE TABLE IF NOT EXISTS ai_use_cases (id TEXT PRIMARY KEY,name TEXT NOT NULL,purpose TEXT NOT NULL,owner TEXT NOT NULL,data_classification TEXT NOT NULL,impact_level TEXT NOT NULL,decision_role TEXT NOT NULL,controls_json TEXT NOT NULL DEFAULT '[]',status TEXT NOT NULL DEFAULT 'draft',review_date TEXT NOT NULL,created_by TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,approved_by TEXT,approved_at TEXT,decision_note TEXT);
CREATE INDEX IF NOT EXISTS ai_use_cases_status_review_idx ON ai_use_cases(status,review_date);
CREATE TABLE IF NOT EXISTS ai_eval_cases (id TEXT PRIMARY KEY,name TEXT NOT NULL,input_text TEXT NOT NULL,expected_terms_json TEXT NOT NULL DEFAULT '[]',forbidden_terms_json TEXT NOT NULL DEFAULT '[]',max_latency_ms INTEGER NOT NULL DEFAULT 30000,enabled INTEGER NOT NULL DEFAULT 1,created_by TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ai_eval_runs (id TEXT PRIMARY KEY,case_id TEXT NOT NULL,provider TEXT NOT NULL,model TEXT NOT NULL,status TEXT NOT NULL,score INTEGER NOT NULL,latency_ms INTEGER NOT NULL,output_hash TEXT,failure_reason TEXT NOT NULL,run_by TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS ai_eval_runs_case_created_idx ON ai_eval_runs(case_id,created_at);
